    def test_consecutive_pairs(self):
        self.assertEqual(deltas(READINGS), [(DT(2025, 1, 6, 15), DT(2025, 1, 6, 21), 6000), (DT(2025, 1, 6, 21), DT(2025, 1, 7, 3), 900)])

